INSERT INTO public.policy_chunks VALUES (413, 14, 5, '三、高校考核和入围名单确定
综合评价招生计划数的5倍确定入围考生名单，并在规定时间内上传管理系统。省教育考试院对入围考生名单进行审核、公示，考生所在中学和入围高校应分别在学校网站进行不少于10个工作日的公示。公示信息应包括考生姓名、所在中学（或单位）、测试项目、测试成绩、合格标准、入围高校及专业等，并保留到当年年底。', NULL, '[-0.015962277,0.020467024,0.012252788,-0.05949448,0.0132775195,0.011435788,0.015987597,0.0001869277,0.010344505,0.017474303,-0.00026353778,0.00016072865,0.028149115,-0.03264166,0.07823782,0.033322368,0.00267707,-0.008357798,-0.012198239,-0.011320419,-0.020595936,0.005214769,-0.010998851,-0.0034923241,0.00684119,-0.019431008,0.036027305,0.005790698,0.0471855,0.009701046,-0.0015855941,0.021953057,0.009313134,0.013092065,0.0035199034,0.018533131,0.018221114,0.016305987,-0.008882716,0.010389617,0.009288188,0.030803638,0.0109783225,-0.0021965418,-0.026554465,-0.012513915,-0.008488447,-0.03213466,-0.009318049,-0.011169276,0.010235747,0.017203722,-0.016602645,-0.15851307,-0.005481859,-0.024313359,-0.011259372,-0.0051395353,-0.0027603172,0.003494802,-0.030455511,0.010544083,-0.01767862,0.010562662,0.0030657048,-0.00020602168,0.0057416367,0.009991238,-0.035257336,-0.015473447,-0.0075541884,-0.010756144,0.014323382,-0.004148452,-0.013977615,-0.021204442,-0.018228654,0.0030531678,-0.012955431,0.006910367,-0.025830634,-0.045062095,0.0134443045,-0.00066961575,0.00691262,-0.027948132,0.01020625,0.0034132674,0.017914744,0.012376681,0.0071167415,0.007083858,-0.014070348,-0.004371024,0.031975903,0.0040950608,-0.023910781,0.0008041671,0.0047969264,-0.01896649,-0.0072272397,-0.01465827,-0.019134566,-0.0011719525,0.014554958,-0.029660117,0.036963154,-0.009285547,0.023398018,-0.023513343,-0.013016175,-0.0124742305,0.013979911,0.005569936,-0.01184669,-0.19951102,0.00077855756,0.011961784,-0.010805184,-0.0028586907,-0.036775645,-0.023426607,-0.014467075,0.0007888498,0.017268356,-0.012385322,0.0063575655,-0.026859893,-0.011648344,-0.011905464,-0.00033302544,0.0050712945,0.005038376,0.00093175325,0.013180028,0.014005126,-0.027035264,-0.029324463,0.005395409,-0.0023621325,-0.0064600674,0.0022177969,0.011550974,-0.0051188287,-0.0144729335,-