INSERT INTO public.policy_chunks VALUES (443, 16, 11, '五、报名流程 > （六）电子照片
电子照片将作为考生本人准考证唯一使用照片，用于考试期间的人像识别比对及毕业电子注册的照片审核。对于在参加普通高中学业水平合格性考试报名时已经采集过照片且符合要求的应届毕业生，在高考报名时可不再进行照片采集，其他考生须在高考报名时采集照片。
电子照片须按照证件照标准采集，头部占照片尺寸的2/3，能反映本人面部特征，人像清晰。文件规格为宽480像素×高640像素，分辨率300dpi，24位真彩色；应符合JPEG标准，压缩后文件大小一般在20KB至40KB；文件扩展名应为JPG。考生不得过度美化和修饰照片，不符合要求的照片会影响考生的考试及毕业，由此造成的后果由考生承担。', NULL, '[-0.02296163,0.027623324,-0.013779204,-0.06282397,0.017600797,0.013565104,0.009470956,-0.020177627,0.0063089095,0.0045389975,-0.021965148,0.013404105,0.003917413,0.016595928,0.102901705,0.009319048,-0.004319031,0.0034827508,-0.018406589,-0.04085334,0.00054619036,0.00420944,-0.030744828,-0.008930245,-0.011161245,-0.004403136,0.016329207,0.012946977,0.03831294,-0.003925212,-0.01395907,0.021102384,0.00719946,0.045341972,-0.0081495205,0.011163876,0.012822417,0.018272493,-0.00018367147,0.004905586,-0.015344452,0.005516047,0.014083953,0.0064178077,-0.0052523273,-0.0056573083,0.011975887,-0.0256785,-0.012862688,0.004804889,0.011964148,0.017891042,-0.050932065,-0.16574706,0.010113672,-0.01787891,-0.002741176,0.009812842,-0.017122691,-0.013575959,0.0063436236,0.03589876,0.0064639836,-0.011091851,-0.0062234565,-0.007910786,0.024498837,0.008016153,-0.028470803,-0.018462397,0.006954188,0.004170317,0.0075689037,0.0018853813,-0.0039041615,0.0008171854,-0.0102822045,-0.018430738,-0.017523075,0.0069667962,-0.036045108,-0.02410381,0.014933765,0.0027713026,0.008162439,-0.026850676,0.00060330424,0.005484743,0.001312922,-0.0100787,0.007643119,-0.011036964,0.018661335,-0.024882438,0.026790796,-0.011001002,-0.02150379,0.015659403,-0.010859855,-0.03514912,0.007769901,-0.01992364,-0.015477679,0.0043908106,0.014896528,-0.027284011,-0.005508381,-0.006946136,0.015864955,-0.023396002,-0.015959973,-0.013536917,0.011017977,0.01770709,0.025493126,-0.1898475,-0.0017773317,0.014143501,0.007765712,0.012086022,-0.005740701,-0.022900317,0.0099538835,0.0011218571,0.0045810994,0.012442285,-0.005571343,-0.024219338,0.012845448,-0.005113716,-0.0027599526,0.0023950867,-0.0067723496,0.00092191016,-0.0006568515,-0.0012026934,-0.044150807,-0.0332801,0.0047591566,0.008325647,0.009540355,-0.0026333458,-0.004555061,-0.02495381,-0.008531798